package com.novacommerce.order.infrastructure.security; import jakarta.servlet.http.*; import org.springframework.security.oauth2.server.resource.web.BearerTokenResolver; import org.springframework.stereotype.Component; @Component public class CookieBearerTokenResolver implements BearerTokenResolver{public String resolve(HttpServletRequest r){Cookie[]c=r.getCookies();if(c!=null)for(Cookie x:c)if("NC_ACCESS".equals(x.getName()))return x.getValue();return null;}}
